function renderDownloads(rows){$("downloadRows").innerHTML=(rows||[]).map(x=>{let mp4="-";if(x.landscape_download_url||x.portrait_download_url){mp4=(x.landscape_download_url?"<a target='_blank' rel='noopener' href='"+esc(x.landscape_download_url)+"'>Landscape MP4</a> ":"")+(x.portrait_download_url?"<a target='_blank' rel='noopener' href='"+esc(x.portrait_download_url)+"'>Portrait MP4</a>":"")}return "<tr><td><b>"+esc(x.title||"-")+"</b><br><a target='_blank' rel='noopener' href='"+esc(x.source_url||"#")+"'>Twitch</a></td><td>"+esc(x.broadcaster_name||x.creator_name||"-")+"<br><span class='mini'>"+esc(x.broadcaster_id||"-")+"</span></td><td>"+esc(x.clip_id||"-")+"</td><td>"+esc(x.access_status||"unknown")+(x.reason?"<br><span class='mini'>"+esc(x.reason)+"</span>":"")+"</td><td>"+mp4+"</td></tr>"}).join("")}
async function refreshDownloads(){const r=await api("/api/twitch/downloads/status");twitchDownloads=r.items||[];renderDownloads(twitchDownloads)}
