const json=(data,status=200)=>new Response(JSON.stringify(data),{status,headers:{"Content-Type":"application/json; charset=utf-8","Cache-Control":"no-store"}});
const uid=()=>crypto.randomUUID();
async function ensureColumn(db,table,column,definition){const info=await db.prepare("PRAGMA table_info("+table+")").all();if(!(info.results||[]).some(x=>x.name===column))await db.prepare("ALTER TABLE "+table+" ADD COLUMN "+column+" "+definition).run();}
async function ensureTwitchSchema(db){
 await db.prepare(`CREATE TABLE IF NOT EXISTS twitch_oauth (id INTEGER PRIMARY KEY CHECK(id=1),user_id TEXT NOT NULL,login TEXT,display_name TEXT,access_token TEXT NOT NULL,refresh_token TEXT NOT NULL,scopes TEXT NOT NULL DEFAULT '[]',expires_at INTEGER,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP)`).run();
 await db.prepare(`CREATE TABLE IF NOT EXISTS twitch_oauth_states (state TEXT PRIMARY KEY,expires_at INTEGER NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP)`).run();
 await db.prepare(`CREATE TABLE IF NOT EXISTS twitch_clip_access (source_id TEXT PRIMARY KEY,clip_id TEXT,broadcaster_id TEXT,broadcaster_name TEXT,access_status TEXT NOT NULL DEFAULT 'unresolved',reason TEXT,checked_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP)`).run();
 await db.prepare(`CREATE TABLE IF NOT EXISTS twitch_broadcaster_access (broadcaster_id TEXT PRIMARY KEY,broadcaster_name TEXT,access_status TEXT NOT NULL DEFAULT 'unknown',reason TEXT,checked_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP)`).run();
 for(const [c,d] of [["twitch_clip_id","TEXT"],["twitch_broadcaster_id","TEXT"],["twitch_resolved_at","TEXT"],["twitch_game_id","TEXT"],["relevance_status","TEXT DEFAULT 'unknown'"]])await ensureColumn(db,"sources",c,d);
}
async function ensureSchema(db){
 await db.prepare(`CREATE TABLE IF NOT EXISTS clip_analysis (source_id TEXT PRIMARY KEY,score INTEGER NOT NULL,relevance_score INTEGER NOT NULL,hook_score INTEGER NOT NULL,format_score INTEGER NOT NULL,score_reason TEXT,analyzed_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP)`).run();
 await db.prepare(`CREATE TABLE IF NOT EXISTS shorts_drafts (id TEXT PRIMARY KEY,source_id TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'draft',title TEXT,script TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP)`).run();
 for(const [c,d] of [["status","TEXT DEFAULT 'draft'"],["title","TEXT"],["script","TEXT"],["created_at","TEXT"],["updated_at","TEXT"],["source_url","TEXT"],["creator_name","TEXT"]])await ensureColumn(db,"shorts_drafts",c,d);
 await db.prepare(`CREATE TABLE IF NOT EXISTS permission_requests (id TEXT PRIMARY KEY,source_id TEXT NOT NULL,contact_method TEXT NOT NULL DEFAULT 'manual',contact_address TEXT,request_message TEXT NOT NULL,request_status TEXT NOT NULL DEFAULT 'draft',response_notes TEXT,evidence_reference TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP)`).run();
 await db.prepare(`CREATE TABLE IF NOT EXISTS jobs (id TEXT PRIMARY KEY,source_id TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'queued_review',target_format TEXT,editorial_note TEXT,output_key TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP)`).run();
 await ensureColumn(db,"jobs","youtube_url","TEXT");
 await ensureColumn(db,"jobs","youtube_status","TEXT DEFAULT 'not_configured'");
}
function cookieValue(request){const list=(request.headers.get("Cookie")||"").split(";"),found=list.find(x=>x.trim().startsWith("gta6_session="));return found?found.trim().slice(13):"";}
function b64url(bytes){let s="";for(const b of bytes)s+=String.fromCharCode(b);return btoa(s).replace(/\+/g,"-").replace(/\//g,"_").replace(/=+$/g,"");}
async function sign(value,secret){const key=await crypto.subtle.importKey("raw",new TextEncoder().encode(secret),{name:"HMAC",hash:"SHA-256"},false,["sign"]);return b64url(new Uint8Array(await crypto.subtle.sign("HMAC",key,new TextEncoder().encode(value))));}
async function makeSession(secret){const expiry=String(Date.now()+43200000);return expiry+"."+await sign(expiry,secret);}
async function authorized(request,env){if(!env.APP_PASSWORD)return false;const parts=cookieValue(request).split(".");if(parts.length!==2||Number(parts[0])<Date.now())return false;return(await sign(parts[0],env.APP_PASSWORD))===parts[1];}
async function readBody(request){try{return await request.json()}catch{return {}}}
function isGta6Relevant(title){const t=String(title||"").toLowerCase();if(/\b(gta\s*v|gta\s*5|gta\s*online|grand theft auto v|grand theft auto online)\b/.test(t))return false;if(/\b(fortnite|counter[\s-]?strike|cs2|valorant|minecraft|roblox|apex legends|call of duty|warzone)\b/.test(t))return false;return /\b(gta\s*6|gta\s*vi|grand theft auto vi|grand theft auto 6)\b/.test(t);}
function scoreClip(title,views,duration){const t=String(title||"").toLowerCase(),keywords=["gta 6","gta vi","grand theft auto vi","vice city","rockstar"],relevance=Math.min(40,keywords.reduce((n,w)=>n+(t.includes(w)?12:0),0)),hooks=["crazy","insane","funny","secret","crash","police","wanted","fail","hidden","first","rare","fight","explosion"],hook=Math.min(35,8+hooks.reduce((n,w)=>n+(t.includes(w)?7:0),0)),format=duration>=10&&duration<=60?25:duration<=90?16:8,bonus=views>=10000?5:views>=1000?3:0;return{score:Math.min(100,relevance+hook+format+bonus),relevance_score:relevance,hook_score:hook,format_score:Math.min(25,format+bonus),score_reason:"GTA VI ilgisi, hook, süre ve izlenme sinyali."};}
async function analyzeSource(db,source,views=0,duration=30){const s=scoreClip(source.title,views,duration);await db.prepare(`INSERT INTO clip_analysis(source_id,score,relevance_score,hook_score,format_score,score_reason,analyzed_at) VALUES(?,?,?,?,?,?,CURRENT_TIMESTAMP) ON CONFLICT(source_id) DO UPDATE SET score=excluded.score,relevance_score=excluded.relevance_score,hook_score=excluded.hook_score,format_score=excluded.format_score,score_reason=excluded.score_reason,analyzed_at=CURRENT_TIMESTAMP`).bind(source.id,s.score,s.relevance_score,s.hook_score,s.format_score,s.score_reason).run();}
async function deriveTokenKey(env){const material=String(env.APP_PASSWORD||"")+"|"+String(env.TWITCH_CLIENT_SECRET||"")+"|gta6-twitch-token-v1",digest=await crypto.subtle.digest("SHA-256",new TextEncoder().encode(material));return crypto.subtle.importKey("raw",digest,{name:"AES-GCM"},false,["encrypt","decrypt"]);}
function bytesToB64(bytes){let s="";for(const b of bytes)s+=String.fromCharCode(b);return btoa(s);}
function b64ToBytes(s){const raw=atob(s),out=new Uint8Array(raw.length);for(let i=0;i<raw.length;i++)out[i]=raw.charCodeAt(i);return out;}
async function encryptSecret(value,env){const iv=crypto.getRandomValues(new Uint8Array(12)),key=await deriveTokenKey(env),cipher=await crypto.subtle.encrypt({name:"AES-GCM",iv},key,new TextEncoder().encode(String(value)));return bytesToB64(iv)+"."+bytesToB64(new Uint8Array(cipher));}
async function decryptSecret(value,env){const[iv,cipher]=String(value||"").split(".");if(!iv||!cipher)throw new Error("Şifreli Twitch token verisi bozuk.");const key=await deriveTokenKey(env),plain=await crypto.subtle.decrypt({name:"AES-GCM",iv:b64ToBytes(iv)},key,b64ToBytes(cipher));return new TextDecoder().decode(plain);}
function twitchRedirectUri(request){return new URL("/auth/twitch/callback",request.url).toString();}
async function createTwitchOAuthUrl(request,env){const state=uid();await env.DB.prepare("INSERT INTO twitch_oauth_states(state,expires_at) VALUES(?,?)").bind(state,Date.now()+600000).run();const params=new URLSearchParams({client_id:env.TWITCH_CLIENT_ID,redirect_uri:twitchRedirectUri(request),response_type:"code",scope:"editor:manage:clips channel:manage:clips",state});return"https://id.twitch.tv/oauth2/authorize?"+params.toString();}
async function exchangeTwitchCode(code,request,env){const response=await fetch("https://id.twitch.tv/oauth2/token",{method:"POST",headers:{"Content-Type":"application/x-www-form-urlencoded"},body:new URLSearchParams({client_id:env.TWITCH_CLIENT_ID,client_secret:env.TWITCH_CLIENT_SECRET,code,grant_type:"authorization_code",redirect_uri:twitchRedirectUri(request)})}),data=await response.json();if(!response.ok||!data.access_token||!data.refresh_token)throw new Error("Twitch OAuth token alınamadı: "+(data.message||data.error||response.status));return data;}
async function twitchValidate(accessToken){const response=await fetch("https://id.twitch.tv/oauth2/validate",{headers:{Authorization:"OAuth "+accessToken}}),data=await response.json();if(!response.ok||!data.user_id)throw new Error("Twitch token doğrulanamadı.");return data;}
async function twitchUser(accessToken,env){const data=await twitchGet("https://api.twitch.tv/helix/users",env,accessToken);return data[0]||null;}
async function saveTwitchOAuth(env,tokenData,profile){await env.DB.prepare(`INSERT INTO twitch_oauth(id,user_id,login,display_name,access_token,refresh_token,scopes,expires_at,updated_at) VALUES(1,?,?,?,?,?,?,?,CURRENT_TIMESTAMP) ON CONFLICT(id) DO UPDATE SET user_id=excluded.user_id,login=excluded.login,display_name=excluded.display_name,access_token=excluded.access_token,refresh_token=excluded.refresh_token,scopes=excluded.scopes,expires_at=excluded.expires_at,updated_at=CURRENT_TIMESTAMP`).bind(profile.id,profile.login||"",profile.display_name||profile.login||"",await encryptSecret(tokenData.access_token,env),await encryptSecret(tokenData.refresh_token,env),JSON.stringify(tokenData.scope||[]),Date.now()+Number(tokenData.expires_in||0)*1000).run();}
async function getTwitchOAuth(db,env){const row=await db.prepare("SELECT * FROM twitch_oauth WHERE id=1").first();if(!row)return null;return{...row,access_token:await decryptSecret(row.access_token,env),refresh_token:await decryptSecret(row.refresh_token,env),scopes:JSON.parse(row.scopes||"[]")};}
async function refreshTwitchOAuth(db,env,row){const response=await fetch("https://id.twitch.tv/oauth2/token",{method:"POST",headers:{"Content-Type":"application/x-www-form-urlencoded"},body:new URLSearchParams({client_id:env.TWITCH_CLIENT_ID,client_secret:env.TWITCH_CLIENT_SECRET,grant_type:"refresh_token",refresh_token:row.refresh_token})}),data=await response.json();if(!response.ok||!data.access_token||!data.refresh_token)throw new Error("Twitch refresh token geçersiz. Twitch bağlantısını yeniden kur.");const profile=await twitchUser(data.access_token,env);if(!profile)throw new Error("Twitch kullanıcı bilgisi alınamadı.");await saveTwitchOAuth(env,data,profile);return await getTwitchOAuth(db,env);}
async function userTwitchToken(db,env){const row=await getTwitchOAuth(db,env);if(!row)return null;try{await twitchValidate(row.access_token);return row}catch(e){return await refreshTwitchOAuth(db,env,row);}}
function extractClipSlug(sourceUrl){try{const u=new URL(sourceUrl);if(!/^(www\.)?twitch\.tv$/i.test(u.hostname))return null;const parts=u.pathname.split("/").filter(Boolean),i=parts.findIndex(x=>x.toLowerCase()==="clip");return i>=0&&parts[i+1]?parts[i+1]:parts[parts.length-1]||null}catch{return null}}
async function countUnresolved(db){const r=await db.prepare("SELECT COUNT(*) AS n FROM sources WHERE platform='twitch' AND (twitch_clip_id IS NULL OR twitch_broadcaster_id IS NULL)").first();return Number(r?.n||0);}
async function accessCounts(db){const r=await db.prepare("SELECT access_status,COUNT(*) AS n FROM twitch_clip_access GROUP BY access_status").all(),out={downloadable:0,unauthorized:0,not_available:0,error:0,resolved:0,unresolved:0};for(const x of(r.results||[]))if(Object.prototype.hasOwnProperty.call(out,x.access_status))out[x.access_status]+=Number(x.n||0);return out;}
async function getDownloadStatus(db){const r=await db.prepare(`SELECT a.source_id,a.clip_id,a.broadcaster_id,a.broadcaster_name,a.access_status,a.reason,a.checked_at,s.title,s.creator_name,s.source_url FROM twitch_clip_access a LEFT JOIN sources s ON s.id=a.source_id ORDER BY a.checked_at DESC LIMIT 500`).all();return{items:r.results||[]};}
async function resolveTwitchClips(db,env,limit=20){const safe=Math.max(1,Math.min(20,Number(limit)||20)),rows=(await db.prepare(`SELECT id,source_url,creator_name,title FROM sources WHERE platform='twitch' AND (twitch_clip_id IS NULL OR twitch_broadcaster_id IS NULL) ORDER BY created_at ASC LIMIT ?`).bind(safe).all()).results||[];if(!rows.length){const result=await getDownloadStatus(db),c=await accessCounts(db);return{processed:0,resolved:0,downloadable:c.downloadable,unauthorized:c.unauthorized,errors:c.error,remaining:await countUnresolved(db),items:result.items};}
const appToken=await twitchToken(env);let resolved=0,errors=0;
for(const source of rows){const slug=extractClipSlug(source.source_url);if(!slug){errors++;await db.prepare(`INSERT INTO twitch_clip_access(source_id,access_status,reason) VALUES(?,?,?) ON CONFLICT(source_id) DO UPDATE SET access_status=excluded.access_status,reason=excluded.reason,checked_at=CURRENT_TIMESTAMP`).bind(source.id,"error","Twitch clip slug çözülemedi.").run();continue;}
try{const data=await twitchGet("https://api.twitch.tv/helix/clips?id="+encodeURIComponent(slug),env,appToken),clip=data[0];if(!clip){errors++;await db.prepare(`INSERT INTO twitch_clip_access(source_id,clip_id,access_status,reason) VALUES(?,?,?,?) ON CONFLICT(source_id) DO UPDATE SET clip_id=excluded.clip_id,access_status=excluded.access_status,reason=excluded.reason,checked_at=CURRENT_TIMESTAMP`).bind(source.id,slug,"error","Twitch API klibi bulamadı.").run();continue;}
await db.prepare("UPDATE sources SET twitch_clip_id=?,twitch_broadcaster_id=?,twitch_resolved_at=CURRENT_TIMESTAMP WHERE id=?").bind(clip.id,clip.broadcaster_id,source.id).run();
await db.prepare(`INSERT INTO twitch_clip_access(source_id,clip_id,broadcaster_id,broadcaster_name,access_status,reason) VALUES(?,?,?,?,?,?) ON CONFLICT(source_id) DO UPDATE SET clip_id=excluded.clip_id,broadcaster_id=excluded.broadcaster_id,broadcaster_name=excluded.broadcaster_name,access_status=excluded.access_status,reason=excluded.reason,checked_at=CURRENT_TIMESTAMP`).bind(source.id,clip.id,clip.broadcaster_id,clip.broadcaster_name||source.creator_name||"Unknown","resolved","Klip bilgisi çözüldü.").run();resolved++;
}catch(e){errors++;await db.prepare(`INSERT INTO twitch_clip_access(source_id,access_status,reason) VALUES(?,?,?) ON CONFLICT(source_id) DO UPDATE SET access_status=excluded.access_status,reason=excluded.reason,checked_at=CURRENT_TIMESTAMP`).bind(source.id,"error",e.message).run();}}
const result=await getDownloadStatus(db),c=await accessCounts(db);return{processed:rows.length,resolved,downloadable:c.downloadable,unauthorized:c.unauthorized,errors,remaining:await countUnresolved(db),items:result.items};}
async function fetchClipDownloads(db,env,row,clipIds){const q=clipIds.map(id=>"id="+encodeURIComponent(id)).join("&"),url="https://api.twitch.tv/helix/clips/downloads?editor_id="+encodeURIComponent(row.user_id)+"&broadcaster_id="+encodeURIComponent(row.broadcaster_id)+"&"+q;try{return await twitchGet(url,env,row.access_token)}catch(e){if(String(e.message).includes("401")){const fresh=await refreshTwitchOAuth(db,env,row),retryUrl="https://api.twitch.tv/helix/clips/downloads?editor_id="+encodeURIComponent(fresh.user_id)+"&broadcaster_id="+encodeURIComponent(row.broadcaster_id)+"&"+q;return await twitchGet(retryUrl,env,fresh.access_token)}throw e;}}
function isEditorPermissionError(error){const m=String(error?.message||error).toLowerCase();return m.includes("editor permissions")||m.includes("editor permission")||m.includes("not have editor")||m.includes("forbidden")||m.includes("unauthorized")||m.includes("403");}
async function markBroadcasterUnauthorized(db,broadcasterId,name,reason,rows){await db.prepare(`INSERT INTO twitch_broadcaster_access(broadcaster_id,broadcaster_name,access_status,reason,checked_at) VALUES(?,?,'unauthorized',?,CURRENT_TIMESTAMP) ON CONFLICT(broadcaster_id) DO UPDATE SET broadcaster_name=excluded.broadcaster_name,access_status='unauthorized',reason=excluded.reason,checked_at=CURRENT_TIMESTAMP`).bind(broadcasterId,name||"Unknown",reason).run();for(const x of rows)await db.prepare("UPDATE twitch_clip_access SET access_status='unauthorized',reason=?,checked_at=CURRENT_TIMESTAMP WHERE source_id=?").bind(reason,x.source_id).run();}
async function checkTwitchDownloads(db,env,limit=20){const resolved=await resolveTwitchClips(db,env,limit),connected=await userTwitchToken(db,env);if(!connected){const st=await getDownloadStatus(db);return{...resolved,items:st.items.map(x=>x.access_status==="resolved"?{...x,reason:"Twitch hesabı bağlı değil; erişim kontrol edilemedi."}:x),skipped_broadcasters:0};}
const all=(await db.prepare(`SELECT a.source_id,a.clip_id,a.broadcaster_id,a.broadcaster_name,s.title,s.creator_name,s.source_url FROM twitch_clip_access a JOIN sources s ON s.id=a.source_id WHERE a.clip_id IS NOT NULL AND a.broadcaster_id IS NOT NULL AND a.access_status NOT IN ('unauthorized','not_available') ORDER BY a.checked_at ASC LIMIT ?`).bind(Math.max(1,Math.min(100,Number(limit)||20))).all()).results||[],groups=new Map();for(const x of all){if(!groups.has(x.broadcaster_id))groups.set(x.broadcaster_id,[]);groups.get(x.broadcaster_id).push(x);}
let apiErrors=0,skippedBroadcasters=0;const temporaryDownloads=[];
for(const[broadcasterId,arr]of groups){const known=await db.prepare("SELECT access_status,reason FROM twitch_broadcaster_access WHERE broadcaster_id=?").bind(broadcasterId).first();if(known&&known.access_status==="unauthorized"){skippedBroadcasters++;for(const x of arr){await db.prepare("UPDATE twitch_clip_access SET access_status='unauthorized',reason=?,checked_at=CURRENT_TIMESTAMP WHERE source_id=?").bind(known.reason||"Bu yayıncı için editör erişimi bulunmuyor.",x.source_id).run();temporaryDownloads.push({...x,access_status:"unauthorized",reason:known.reason||"Bu yayıncı için editör erişimi bulunmuyor."});}continue;}
for(let i=0;i<arr.length;i+=10){const batch=arr.slice(i,i+10);try{const data=await fetchClipDownloads(db,env,{...connected,broadcaster_id:broadcasterId},batch.map(x=>x.clip_id)),found=new Map((data||[]).map(x=>[x.clip_id,x]));for(const x of batch){const d=found.get(x.clip_id);if(d&&(d.landscape_download_url||d.portrait_download_url)){await db.prepare("UPDATE twitch_clip_access SET access_status='downloadable',reason=?,checked_at=CURRENT_TIMESTAMP WHERE source_id=?").bind("Twitch indirme URL'si üretildi. URL geçicidir.",x.source_id).run();temporaryDownloads.push({...x,access_status:"downloadable",reason:"Geçici Twitch indirme URL'si.",landscape_download_url:d.landscape_download_url||null,portrait_download_url:d.portrait_download_url||null});}else{await db.prepare("UPDATE twitch_clip_access SET access_status='not_available',reason=?,checked_at=CURRENT_TIMESTAMP WHERE source_id=?").bind("Twitch indirme URL'si mevcut değil.",x.source_id).run();temporaryDownloads.push({...x,access_status:"not_available",reason:"Twitch indirme URL'si mevcut değil."});}}}
catch(e){if(isEditorPermissionError(e)){const reason="Twitch API: Bu yayıncı için hesabın editör izni yok. Yayıncı sonraki kontrollerde atlanacak.";await markBroadcasterUnauthorized(db,broadcasterId,batch[0]?.broadcaster_name||"Unknown",reason,batch);for(const x of batch)temporaryDownloads.push({...x,access_status:"unauthorized",reason});}else{apiErrors++;for(const x of batch){await db.prepare("UPDATE twitch_clip_access SET access_status='error',reason=?,checked_at=CURRENT_TIMESTAMP WHERE source_id=?").bind(e.message,x.source_id).run();temporaryDownloads.push({...x,access_status:"error",reason:e.message});}}}}}
const st=await getDownloadStatus(db),statusById=new Map(st.items.map(x=>[x.source_id,x]));for(const x of temporaryDownloads)statusById.set(x.source_id,x);const c=await accessCounts(db);return{processed:resolved.processed,resolved:resolved.resolved,downloadable:c.downloadable,unauthorized:c.unauthorized,errors:resolved.errors+apiErrors,remaining:await countUnresolved(db),skipped_broadcasters:skippedBroadcasters,items:Array.from(statusById.values()).sort((a,b)=>String(b.checked_at||"").localeCompare(String(a.checked_at||"")))};}
async function twitchToken(env){if(!env.TWITCH_CLIENT_ID||!env.TWITCH_CLIENT_SECRET)throw new Error("Twitch API secrets eksik.");const response=await fetch("https://id.twitch.tv/oauth2/token",{method:"POST",headers:{"Content-Type":"application/x-www-form-urlencoded"},body:new URLSearchParams({client_id:env.TWITCH_CLIENT_ID,client_secret:env.TWITCH_CLIENT_SECRET,grant_type:"client_credentials"})}),data=await response.json();if(!response.ok||!data.access_token)throw new Error("Twitch kimlik doğrulaması başarısız.");return data.access_token;}
async function twitchGet(url,env,token){const response=await fetch(url,{headers:{"Client-Id":env.TWITCH_CLIENT_ID,"Authorization":"Bearer "+token}}),data=await response.json();if(!response.ok)throw new Error("Twitch API: "+(data.message||response.status));return data.data||[];}
async function getGta6GameId(env,token){for(const name of["Grand Theft Auto VI","GTA VI"]){const games=await twitchGet("https://api.twitch.tv/helix/games?name="+encodeURIComponent(name),env,token),exact=games.find(g=>{const n=String(g.name||"").trim().toLowerCase();return n==="grand theft auto vi"||n==="gta vi"});if(exact)return exact.id;}return null;}
async function discover(db,env){const token=await twitchToken(env),gameId=await getGta6GameId(env,token);let clips=0,saved=0,duplicates=0,filtered=0;const creators=new Map();
async function saveClip(clip,creatorFallback=null){clips++;const title=clip.title||"Untitled clip",categoryName=String(clip.game_name||"").toLowerCase(),categoryConfirmed=categoryName==="grand theft auto vi"||categoryName==="gta vi"||(!!gameId&&String(clip.game_id||"")===String(gameId));if(!categoryConfirmed&&!isGta6Relevant(title)){filtered++;return;}const exists=await db.prepare("SELECT id FROM sources WHERE source_url=? LIMIT 1").bind(clip.url).first();if(exists){duplicates++;return;}const id=uid(),creatorName=clip.broadcaster_name||creatorFallback?.display_name||creatorFallback?.broadcaster_name||"Unknown";if(clip.broadcaster_id)creators.set(clip.broadcaster_id,{id:clip.broadcaster_id,display_name:creatorName});await db.prepare(`INSERT INTO sources(id,platform,source_url,creator_name,title,rights_status,twitch_game_id,relevance_status,twitch_broadcaster_id) VALUES(?,?,?,?,?,'pending',?,?,?)`).bind(id,"twitch",clip.url,creatorName,title,gameId||clip.game_id||null,"relevant",clip.broadcaster_id||null).run();await analyzeSource(db,{id,title},clip.view_count||0,clip.duration||30);saved++;}
if(gameId){const items=await twitchGet("https://api.twitch.tv/helix/clips?game_id="+encodeURIComponent(gameId)+"&first=100",env,token);for(const clip of items)await saveClip(clip)}else{const queries=["GTA VI","GTA 6","Grand Theft Auto VI"],channels=new Map();for(const q of queries){const found=await twitchGet("https://api.twitch.tv/helix/search/channels?query="+encodeURIComponent(q)+"&first=30",env,token);for(const c of found)if(c.id)channels.set(c.id,c);}for(const creator of Array.from(channels.values()).slice(0,30)){const items=await twitchGet("https://api.twitch.tv/helix/clips?broadcaster_id="+encodeURIComponent(creator.id)+"&first=20",env,token);for(const clip of items)await saveClip(clip,creator);}}
return{creators:creators.size,clips,saved,duplicates,filtered,game_id:gameId||null};}
function makeEditorialPackage(source){const originalTitle=String(source.title||"GTA VI Moment").trim(),clean=originalTitle.replace(/\s+/g," ").slice(0,110),t=clean.toLowerCase();let angle="moment",hook="This GTA 6 moment deserves a closer look.",narration="The title points to an interesting GTA 6 moment. Watch the sequence closely, notice the details, and decide what stands out most to you.",captions=["A GTA 6 MOMENT WORTH WATCHING","LOOK CLOSELY","WHAT STOOD OUT TO YOU?"],question="What would you have noticed first?";
const rules=[{keys:["crash","car accident","collision","wreck","drift"],angle:"vehicle",hook:"One moment can change the whole drive in GTA 6.",narration:"This title points to a driving moment in GTA 6. Pay attention to the timing, the movement, and what happens around the vehicle. Would you have handled it differently?",captions:["GTA 6 DRIVING MOMENT","WATCH THE TIMING","HOW WOULD YOU REACT?"],question:"Would you have avoided it?"},{keys:["police","cop","wanted","arrest","chase"],angle:"police",hook:"A GTA 6 police moment you don't want to miss.",narration:"This clip title suggests a police encounter in GTA 6. Watch how the situation develops and look for the detail that changes the moment. What would your next move be?",captions:["GTA 6 POLICE MOMENT","WATCH WHAT HAPPENS","WHAT'S YOUR NEXT MOVE?"],question:"Would you run or stay?"},{keys:["funny","laugh","hilarious","fail","embarrassing"],angle:"comedy",hook:"GTA 6 moments like this are hard to predict.",narration:"The title frames this as a funny GTA 6 moment. The fun is in the timing, so watch the full sequence before deciding what makes it work. Which part got you?",captions:["GTA 6 FUNNY MOMENT","THE TIMING IS EVERYTHING","DID YOU LAUGH?"],question:"Which part was funniest?"},{keys:["secret","hidden","easter egg","mystery"],angle:"discovery",hook:"Could this be a detail worth looking for in GTA 6?",narration:"This title points toward a possible hidden detail or mystery. Take a close look at what the clip actually shows and decide whether it reveals something easy to miss.",captions:["GTA 6 DETAIL TO CHECK","LOOK CLOSER","DID YOU SPOT IT?"],question:"Did you notice it immediately?"},{keys:["explosion","explode","bomb","fire"],angle:"explosion",hook:"Keep your eyes on this GTA 6 moment.",narration:"The title suggests an explosive moment in GTA 6. Watch the full sequence and pay attention to the build-up and timing. What detail stood out to you?",captions:["GTA 6 ACTION MOMENT","WATCH THE BUILD-UP","WHAT STOOD OUT?"],question:"Did you expect that?"},{keys:["fight","punch","battle","combat","attack"],angle:"combat",hook:"A split-second decision can change a GTA 6 fight.",narration:"This title suggests a combat moment. Watch the positioning and timing, then decide what move made the biggest difference. What would you have done?",captions:["GTA 6 COMBAT MOMENT","WATCH THE TIMING","YOUR NEXT MOVE?"],question:"Which move would you choose?"},{keys:["graphic","detail","realistic","realism","physics"],angle:"detail",hook:"This is the kind of GTA 6 detail worth examining.",narration:"The title draws attention to a visual or gameplay detail. Look closely at the actual footage and decide what makes this moment interesting. Is this the kind of detail you want to see more often?",captions:["GTA 6 DETAIL CHECK","LOOK AT THE SMALL THINGS","DID YOU NOTICE?"],question:"Would you like more details like this?"},{keys:["mission","heist","robbery"],angle:"mission",hook:"Every decision matters in a GTA 6 mission.",narration:"This title points to a mission or heist-related moment. Follow the sequence and pay attention to the choices being made. What would your approach have been?",captions:["GTA 6 MISSION MOMENT","WATCH THE DECISIONS","WHAT'S YOUR PLAN?"],question:"How would you approach it?"},{keys:["character","lucia","jason"],angle:"character",hook:"Let's take a closer look at this GTA 6 character moment.",narration:"The title points to a character-focused moment in GTA 6. Pay attention to the presentation and the details visible in the clip. What stands out most to you?",captions:["GTA 6 CHARACTER MOMENT","WATCH THE DETAILS","WHO STOOD OUT?"],question:"Which character interests you most?"}];
for(const rule of rules){if(rule.keys.some(k=>t.includes(k))){angle=rule.angle;hook=rule.hook;narration=rule.narration;captions=rule.captions;question=rule.question;break;}}
const title="GTA 6: "+clean+" 👀",captionText=captions.join("\n"),script="SHORTS EDITORIAL PRODUCTION PACKAGE · 3.6\n\nSOURCE: "+(source.source_url||"")+"\nCREATOR: "+(source.creator_name||"Unknown")+"\nORIGINAL CLIP TITLE: "+originalTitle+"\nEDITORIAL ANGLE: "+angle+"\n\nPROPOSED TITLE:\n"+title+"\n\nHOOK / OPENING:\n"+hook+"\n\nORIGINAL VOICEOVER DRAFT:\n"+narration+"\n\nCAPTION TEXT DRAFT:\n"+captionText+"\n\nENDING QUESTION:\n"+question+"\n\n9:16 EDITING PLAN:\n1. Create a vertical 1080x1920 sequence.\n2. Start with the strongest visually verified moment; do not invent an event from the title.\n3. Keep the main subject inside the central safe area.\n4. Use the hook in the first 1-2 seconds.\n5. Add the voiceover as original commentary, not as a claim about unseen footage.\n6. Synchronize short captions with the actual footage.\n7. Remove dead time while preserving the context of the clip.\n8. Finish with the question above and a clean final frame.\n\nEDITORIAL NOTE:\nThis package is tailored to the source title and its detected topic. The actual clip has not been visually or audibly analyzed by this Worker. Verify every statement against the footage before editing.\n\nPRODUCTION STATUS:\nEditorial package ready. After documented rights approval, this draft can be sent to the cloud MP4 renderer from the dashboard.\nThe Worker has not visually or audibly analyzed the actual clip; verify all claims against the footage before publication.";return{title,script};}
function extractNarration(script){const m=String(script||"").match(/ORIGINAL VOICEOVER DRAFT:\s*([\s\S]*?)\n\nCAPTION TEXT DRAFT:/);return m?m[1].trim():"";}
async function dispatchRender(db,env,draftId,evidenceReference,authorizationConfirmation){
 if(!env.GITHUB_TOKEN)return {error:"Cloudflare Worker'da GITHUB_TOKEN secret eksik. GitHub Actions workflow_dispatch yetkili token eklenmeli."};
 const row=await db.prepare(`SELECT d.id AS draft_id,d.source_id,d.title AS draft_title,d.script,d.status AS draft_status,s.source_url,s.title AS source_title,s.creator_name,s.rights_status,j.id AS job_id,j.status AS job_status FROM shorts_drafts d JOIN sources s ON s.id=d.source_id LEFT JOIN jobs j ON j.source_id=s.id WHERE d.id=? ORDER BY j.created_at DESC LIMIT 1`).bind(draftId).first();
 if(!row)return {error:"Üretim paketi bulunamadı."};
 if(!row.job_id)return {error:"Bu paket için üretim işi kaydı bulunamadı. Önce paketleri güncelle."};
 if(row.rights_status!=="approved"){
  const evidence=String(evidenceReference||"").trim();
  const confirmation=String(authorizationConfirmation||"").trim();
  if(evidence.length<8||confirmation!=="I CONFIRM I HAVE PERMISSION")return {error:"Render engellendi: kullanım izni kanıtı ve açık onay gerekli. Kanıt tek başına izin yerine geçmez."};
  await db.prepare("UPDATE sources SET rights_status='approved' WHERE id=?").bind(row.source_id).run();
  await db.prepare("INSERT INTO permission_requests(id,source_id,contact_method,request_message,request_status,response_notes,evidence_reference,created_at,updated_at) VALUES(?,?,'manual',?,'approved',?,?,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)").bind(uid(),row.source_id,"User explicitly confirmed they hold permission to reuse this clip for a Short.", "Explicit user confirmation recorded; evidence reference supplied: "+evidence, evidence).run();
 }
 if(["dispatching","rendering","rendered"].includes(row.job_status))return {error:"Bu paket zaten render kuyruğunda veya tamamlanmış."};
 const narration=extractNarration(row.script);
 if(narration.length<20)return {error:"Üretim metninden voiceover çıkarılamadı; render başlatılmadı."};
 const title=String(row.draft_title||row.source_title||"GTA 6 Short").slice(0,90);
 const questionMatch=String(row.script||"").match(/ENDING QUESTION:\s*([^\n]+)/);
 const description=["GTA 6 clip featuring "+String(row.source_title||title).slice(0,180)+".","Clip creator: "+String(row.creator_name||"Unknown").slice(0,100)+".",questionMatch?questionMatch[1].trim():"What stood out to you?","#GTA6 #GTAVI #Shorts"].join("\n\n").slice(0,5000);
 await db.prepare("UPDATE jobs SET status='dispatching',editorial_note='Authorized render dispatched to GitHub Actions.',updated_at=CURRENT_TIMESTAMP WHERE id=?").bind(row.job_id).run();
 await db.prepare("UPDATE shorts_drafts SET status='rendering',updated_at=CURRENT_TIMESTAMP WHERE id=?").bind(row.draft_id).run();
 let response;
 try{response=await fetch("https://api.github.com/repos/alperengkhn-sys/gta6-shorts-factory/actions/workflows/render-short.yml/dispatches",{method:"POST",headers:{"Authorization":"Bearer "+env.GITHUB_TOKEN,"Accept":"application/vnd.github+json","X-GitHub-Api-Version":"2022-11-28","Content-Type":"application/json","User-Agent":"GTA6-Shorts-Factory"},body:JSON.stringify({ref:"main",inputs:{source_url:row.source_url,title,description,narration,rights_approved:"true",job_id:row.job_id}})});}
 catch(error){const detail=String(error&&error.message||error).slice(0,1000);await db.prepare("UPDATE jobs SET status='dispatch_failed',editorial_note=?,updated_at=CURRENT_TIMESTAMP WHERE id=?").bind("GitHub dispatch network error: "+detail,row.job_id).run();await db.prepare("UPDATE shorts_drafts SET status='render_failed',updated_at=CURRENT_TIMESTAMP WHERE id=?").bind(row.draft_id).run();return {error:"GitHub Actions bağlantı hatası: "+detail};}
 if(response.status!==204){const detail=(await response.text()).slice(0,1200);await db.prepare("UPDATE jobs SET status='dispatch_failed',editorial_note=?,updated_at=CURRENT_TIMESTAMP WHERE id=?").bind("GitHub dispatch failed: HTTP "+response.status+" "+detail,row.job_id).run();await db.prepare("UPDATE shorts_drafts SET status='render_failed',updated_at=CURRENT_TIMESTAMP WHERE id=?").bind(row.draft_id).run();return {error:"GitHub Actions işi başlatılamadı (HTTP "+response.status+"). "+detail};}
 return {ok:true,job_id:row.job_id,status:"rendering"};
}
async function renderCallback(request,env,db){
 if(!env.RENDER_WEBHOOK_SECRET||request.headers.get("X-Render-Secret")!==env.RENDER_WEBHOOK_SECRET)return json({error:"Webhook authentication failed."},401);
 const data=await readBody(request),jobId=String(data.job_id||"");
 if(!jobId)return json({error:"job_id required."},400);
 const job=await db.prepare("SELECT id,source_id FROM jobs WHERE id=?").bind(jobId).first();
 if(!job)return json({error:"Job not found."},404);
 const ok=(data.render_conclusion||data.conclusion)==="success",status=ok?"rendered":"render_failed",output=String(data.artifact_url||data.run_url||"").slice(0,2000),youtubeStatus=String(data.youtube_status||"not_run").slice(0,40),youtubeUrl=String(data.youtube_url||"").slice(0,1000);
 const note=[ok?"Render completed.":"Render failed.", "YouTube: "+youtubeStatus, data.error||""].filter(Boolean).join(" ").slice(0,1500);
 await db.prepare("UPDATE jobs SET status=?,output_key=?,youtube_url=?,youtube_status=?,editorial_note=?,updated_at=CURRENT_TIMESTAMP WHERE id=?").bind(status,output,youtubeUrl,youtubeStatus,note,jobId).run();
 await db.prepare("UPDATE shorts_drafts SET status=?,updated_at=CURRENT_TIMESTAMP WHERE source_id=?").bind(status,job.source_id).run();
 return json({ok:true,status});
}
async function prepareAll(db){const result=await db.prepare(`SELECT s.id,s.title,s.creator_name,s.source_url,s.rights_status,s.relevance_status,s.twitch_game_id,a.score FROM sources s LEFT JOIN clip_analysis a ON a.source_id=s.id ORDER BY s.created_at ASC`).all(),rows=result.results||[];let created=0,updated=0,existing=0,skippedIrrelevant=0;const statements=[];
for(const source of rows){const categoryConfirmed=!!source.twitch_game_id,markedRelevant=source.relevance_status==="relevant",titleRelevant=isGta6Relevant(source.title);if(!categoryConfirmed&&!markedRelevant&&!titleRelevant){skippedIrrelevant++;continue;}const pack=makeEditorialPackage(source),found=await db.prepare("SELECT id,status FROM shorts_drafts WHERE source_id=? LIMIT 1").bind(source.id).first();if(found){existing++;await db.prepare("UPDATE shorts_drafts SET title=?,script=?,source_url=?,creator_name=?,updated_at=CURRENT_TIMESTAMP WHERE id=?").bind(pack.title,pack.script,source.source_url,source.creator_name||"Unknown",found.id).run();const existingJob=await db.prepare("SELECT id FROM jobs WHERE source_id=? LIMIT 1").bind(source.id).first();if(!existingJob)await db.prepare("INSERT INTO jobs(id,source_id,status,target_format,editorial_note,output_key) VALUES(?,?,'queued_review','shorts_9_16','Legacy draft migrated to cloud render queue.',NULL)").bind(uid(),source.id).run();updated++;continue;}const draftId=uid();statements.push(db.prepare(`INSERT INTO shorts_drafts(id,source_id,status,title,script,created_at,updated_at,source_url,creator_name) VALUES (?,?,'queued_review',?,?,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,?,?)`).bind(draftId,source.id,pack.title,pack.script,source.source_url,source.creator_name||"Unknown"));statements.push(db.prepare(`INSERT INTO jobs(id,source_id,status,target_format,editorial_note,output_key) VALUES (?,?,'queued_review','shorts_9_16',?,NULL)`).bind(uid(),source.id,"Editorial package prepared. Rights status: "+source.rights_status+". Cloud rendering requires documented rights approval."));created++;}
for(let i=0;i<statements.length;i+=40)await db.batch(statements.slice(i,i+40));const total=await db.prepare("SELECT COUNT(*) AS n FROM shorts_drafts WHERE status='queued_review'").first();return{checked:rows.length,created,updated,existing,skipped_irrelevant:skippedIrrelevant,total:Number(total?.n||0)};}
async function getData(db){const sources=await db.prepare(`SELECT s.id,s.platform,s.source_url,s.creator_name,s.title,s.rights_status,s.relevance_status,s.twitch_game_id,a.score FROM sources s LEFT JOIN clip_analysis a ON a.source_id=s.id ORDER BY s.created_at DESC LIMIT 500`).all(),drafts=await db.prepare(`SELECT d.id,d.source_id,d.status,d.title,d.script,d.source_url,d.creator_name,d.created_at,s.rights_status,j.status AS job_status,j.output_key,j.youtube_status,j.youtube_url FROM shorts_drafts d JOIN sources s ON s.id=d.source_id LEFT JOIN jobs j ON j.source_id=d.source_id ORDER BY d.created_at DESC LIMIT 500`).all();return{sources:sources.results||[],drafts:drafts.results||[]};}
async function runScheduled(env){
 if(!env.DB)return {error:"D1 binding missing"};
 await ensureSchema(env.DB);await ensureTwitchSchema(env.DB);
 let discovery;
 try{discovery=await discover(env.DB,env);}catch(error){discovery={error:String(error&&error.message||error).slice(0,500)};}
 const prepared=await prepareAll(env.DB);
 let dispatched=0,dispatchErrors=0;
 if(env.GITHUB_TOKEN){
  const candidates=await env.DB.prepare(`SELECT d.id AS draft_id FROM shorts_drafts d JOIN sources s ON s.id=d.source_id JOIN jobs j ON j.source_id=s.id WHERE s.rights_status='approved' AND j.status IN ('queued_review','dispatch_failed') ORDER BY j.created_at ASC LIMIT 2`).all();
  for(const row of candidates.results||[]){
   const result=await dispatchRender(env.DB,env,row.draft_id,"");
   if(result.ok)dispatched++;else if(result.error){dispatchErrors++;console.error("Scheduled render dispatch:",result.error);}
  }
 }
 return {discovery,prepared,dispatched,dispatchErrors};
}
